import {mountSeedExperience} from '../seed-experience.js';
import {risks} from './predict.js';
import {cropIntelligence} from './crop.js';
import {rotationPlanner} from './planner.js';
import {explain,xmlPrompt} from './xai.js';
import {renderInteractiveSimulatorCard,renderFriendlyMLTranslation} from '../visual-sim.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fixed=v=>Number.isFinite(v)?v.toFixed(2):'Sin datos';
function download(name,data,type='application/json'){const u=URL.createObjectURL(new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
const opts=(a,value)=>a.map(([v,label])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`).join('');
export function mountAI(container,context){
 const root=document.createElement('div');container.replaceChildren(root);let input={...context.farm},ml=null,report=null,rows=context.rows,source=context.source;
 root.innerHTML=`<div class="card hero"><small>METODOLOGÍA NORTEX · VERSIÓN 2</small><h2 style="font-size:25px;margin-top:12px">Comprende tu campo, paso a paso.</h2><p>Condiciones → consecuencias → alternativas → explicación. Explora las simulaciones visuales para comprender qué ocurre en tu parcela sin depender de datos en crudo.</p></div><div class="steps"><div class="card"><b>A / PREDICT</b><p>Observa qué cambia cuando hay menos agua o más calor.</p></div><div class="card"><b>B / CULTIVOS</b><p>Comprende qué condiciones encajan con tu cultivo.</p></div><div class="card"><b>C / PLANIFICADOR</b><p>Compara opciones según el agua y el tiempo disponibles.</p></div><div class="card"><b>D / SEMILLA & XAI</b><p>Guarda una representación visual de tu escenario.</p></div></div><div id="aiVisualSimulator"></div><div class="grid" style="margin-top:22px"><div class="card"><h2>1. Preparar el escenario agrícola</h2><p>Puedes ajustar los valores aquí o desde los controles del simulador interactivo superior. Exporta el informe para conservar tu evaluación.</p><details><summary>Ver o editar las lecturas del escenario</summary><form id="aiInputs" class="fields"><label class="full">Origen de las lecturas<select name="provenance"><option value="demostración / escenario hipotético">Demostración / escenario hipotético</option><option value="ingresado por usuario, sin verificación independiente">Lecturas propias, ingresadas por mí</option></select></label><label>Cultivo<select name="crop">${opts(['Mango Kent','Mango Haden','Limón Sutil'].map(v=>[v,v]),input.crop)}</select></label><label>Etapa<select name="stage">${opts(['poda','inducción floral','floración','cuajado','llenado de fruto'].map(v=>[v,v]),input.stage)}</select></label><label>Textura del suelo<select name="soil">${opts(['arenoso','franco arenoso','franco','arcilloso'].map(v=>[v,v]),input.soil)}</select></label>${[['moisture','Humedad superficial (%)',0,100],['surface','Temperatura superficial (°C)',-50,80],['rain','Lluvia últimos 7 días (mm)',0,5000],['days','Días desde el último riego',0,3650]].map(([k,l,min,max])=>`<label>${l}<input name="${k}" type="number" min="${min}" max="${max}" step="0.1" value="${esc(input[k]??'')}" placeholder="Sin dato"></label>`).join('')}<label>Disponibilidad de agua<select name="water">${opts([[1,'Baja'],[2,'Media'],[3,'Alta']],input.water)}</select></label><label>Lote anual separado<select name="annual">${opts([['false','No disponible'],['true','Disponible']],input.annual)}</select></label><label>Horizonte (meses)<input name="horizon" type="number" min="1" max="60" value="${input.horizon}" required></label><label>Prioridad<select name="priority">${opts([['agua','Ahorrar agua'],['ciclo','Ciclo corto'],['ingreso','Potencial económico ordinal']],input.priority)}</select></label><button class="primary full">Evaluar los módulos agrícolas</button></form></details></div><div class="card"><h2>2. Experimento de temperatura</h2><p id="aiSource"></p><p>¿Qué temperatura del aire calcularía el modelo para el día siguiente al último registro? Aprende con el histórico de 2025; no es el pronóstico actual.</p><div class="row"><span>Entrenamiento</span><strong>Enero–septiembre 2025</strong></div><div class="row"><span>Evaluación temporal</span><strong>Octubre–diciembre 2025</strong></div><div class="row"><span>Random Forest</span><strong>40 árboles · profundidad 5</strong></div><p>Comparación contra persistencia sobre exactamente los mismos días. Mínimo 120 muestras para entrenar y 30 para evaluar.</p><button id="aiNASA">Cargar NASA de esta zona</button> <button class="primary" id="aiTrain">Calcular y explicármelo</button><p>Al cargar, se envían a NASA solo las coordenadas del punto de referencia: ${context.point.lat.toFixed(4)}, ${context.point.lon.toFixed(4)}. No es un promedio del polígono.</p><p id="aiStatus" role="status"></p><div id="aiML"></div></div></div><div id="aiResults" style="margin-top:22px"></div>`;
 const $=s=>root.querySelector(s);const setSource=()=>{$('#aiSource').textContent=`Fuente: ${source} · ${rows.length} días`;$('#aiTrain').disabled=!source.startsWith('NASA POWER');};setSource();
 function syncFormFromInput(){const form=$('#aiInputs');if(!form)return;for(const k of ['crop','stage','soil','moisture','surface','rain','days','water','horizon','priority']){if(form.elements[k]&&input[k]!==undefined&&input[k]!==null)form.elements[k].value=String(input[k]);}if(form.elements.annual)form.elements.annual.value=String(Boolean(input.annual));}
 function update(fromSimulator=false){if(!fromSimulator){const data=Object.fromEntries(new FormData($('#aiInputs')));input={...input,...data};for(const key of ['moisture','surface','rain','days','water','horizon'])input[key]=data[key]===''?null:Number(data[key]);input.annual=data.annual==='true';}else{syncFormFromInput();}
 const r=risks(input),crop=cropIntelligence(input,r),planner=rotationPlanner(input);report={schema:'nortex-ai-report-2',created_at:new Date().toISOString(),point:context.point,geometry:context.area?.geojson||null,climate_dataset:{source,rows},input,provenance:$('#aiInputs')?.elements?.provenance?.value||'demostración / escenario hipotético',risks:r,crop,planner,ml};report.explanation=explain(report);
 if(!fromSimulator)renderInteractiveSimulatorCard($('#aiVisualSimulator'),input,{onChange:patch=>{input={...input,...patch};$('#aiInputs').elements.provenance.value='demostración / escenario hipotético';update(true);}});
 drawResults();}
 $('#aiInputs').onsubmit=e=>{e.preventDefault();update(false);};
 function drawResults(){const r=report.risks,c=report.crop,p=report.planner;$('#aiResults').innerHTML=`<div class="notice">Escenario agrícola: ${esc(report.provenance)}. Las reglas y categorías económicas son experimentales; no están calibradas con agricultores.</div><div class="tree-simple-results"><article><small>1 / QUÉ MIRAR</small><h3>Las señales de tu campo</h3><p>${r.missing.length?'Faltan datos para interpretar este escenario.':r.water>=35?'Empieza por comprobar el agua del suelo. Una superficie seca no dice por sí sola cómo están las raíces.':r.heat>=25?'Presta atención al calor. Revisa hojas y flores y contrasta con mediciones.':'Las reglas no muestran una señal fuerte de agua o calor. Sigue observando el campo.'}</p></article><article><small>2 / CÓMO ENCAJA EL CULTIVO</small><h3>Condiciones para tu cultivo</h3><p>${c.score===undefined?'Necesitamos completar los datos antes de comparar.':c.score>=75?'Según estas reglas, las condiciones encajan relativamente bien con el cultivo.':c.score>=50?'Hay condiciones que conviene revisar antes de tomar decisiones.':'Varias condiciones encajan poco con el cultivo en este escenario.'} El puntaje no indica cuánto vas a cosechar ni la probabilidad de que el árbol sobreviva.</p></article><article><small>3 / TU SIGUIENTE PASO</small><h3>Decide con apoyo</h3><p>${esc(p.recommended?'Una alternativa para revisar con tu técnico es '+p.recommended+'.':p.perennial_action||'Revisa agua disponible, tiempo y si tienes un lote anual separado.')} La comparación no calcula ganancias reales.</p></article></div><div id="aiSeedExperience"></div><details class="tree-technical"><summary>Quiero ver los números y cómo se calcularon</summary><div class="grid"><div class="card"><h2>A · Predict — interpretación de riesgos</h2>${r.missing.length?`<p>Datos insuficientes: ${esc(r.missing.join(', '))}. No se calcula IVAP.</p>`:`<div style="display:flex;justify-content:space-between;align-items:baseline"><div><small>VULNERABILIDAD INDICATIVA</small><strong style="font-size:36px;display:block;margin-top:4px">${r.ivap}<small style="font-size:15px"> / 100</small></strong></div><span class="pill ${r.status!=='NORMAL'?'warn':''}">${esc(r.status)}</span></div><div class="row"><span>Condición hídrica (${input.moisture}% · ${input.days} días)</span><strong>${r.water>=60?'Déficit elevado':r.water>=35?'Atención moderada':'Reserva adecuada'}</strong></div><div class="row"><span>Condición térmica (${input.surface} °C)</span><strong>${r.heat>=50?'Estrés térmico en etapa sensible':r.heat>=25?'Calor moderado':'Rango estable'}</strong></div><div class="row"><span>Condición por lluvia (${input.rain} mm / 7d)</span><strong>${r.rain>=40?'Requiere inspección fitosanitaria':'Baja presión por lluvia'}</strong></div><details style="margin-top:12px"><summary>Ver desglose técnico de reglas (H1, T1, F1)</summary>${r.trace.map(t=>`<p><strong>${t.rule}:</strong> indicador ${fixed(t.score)} · aporte al IVAP ${fixed(t.contribution)}<br><small>${esc(t.formula)}</small></p>`).join('')}</details>`}</div><div class="card"><h2>B · Crop Intelligence</h2>${c.score===undefined?`<p>Datos insuficientes: ${esc(c.missing.join(', '))}.</p>`:`<div style="display:flex;justify-content:space-between;align-items:baseline"><div><small>COMPATIBILIDAD INDICATIVA</small><strong style="font-size:36px;display:block;margin-top:4px">${c.score}<small style="font-size:15px"> / 100</small></strong></div><span class="pill">${esc(c.crop)} · ${esc(c.stage)}</span></div><div class="bar"><i style="width:${c.score}%"></i></div>${c.penalties.map(t=>`<div class="row"><span>${esc(t.reason)}</span><strong>−${fixed(t.value)} pts</strong></div>`).join('')}<p>100 menos penalizaciones por agua, calor, lluvia y textura. No es predicción de rendimiento.</p>`}</div></div><div class="card" style="margin-top:22px"><h2>C · Rotation Planner</h2><p>${esc(p.method||p.status)}</p><div class="scroll"><table><tr><th>Alternativa</th><th>Meses</th><th>Agua</th><th>Puntaje</th><th>Estado y restricciones</th></tr>${p.alternatives.map(a=>`<tr><td>${esc(a.name)}</td><td>${a.months??"Por validar"}</td><td>${a.water===null?"Por validar":"Nivel "+a.water+"/3"}</td><td>${a.score??"Sin puntaje"}</td><td><span class="pill ${a.reasons.length?'warn':''}">${esc(a.reasons.join(' · ')||'Candidata para validación')}</span></td></tr>`).join('')}</table></div><p>${esc(p.recommended?'Candidata: '+p.recommended:p.perennial_action||'Completa los datos de planificación.')}</p></div><div class="card" style="margin-top:22px"><h2>D · Explicabilidad agronómica — XAI</h2>${report.explanation.paragraphs.map(t=>`<p>${esc(t)}</p>`).join('')}<button id="aiReport">Descargar informe y modelo</button> <button id="aiXML">Descargar prompt XML</button><details style="margin-top:12px"><summary>Metodología y límites del experimento</summary><p>Bootstrap de muestras y dos variables aleatorias por nodo. Árboles CART con pérdida cuadrática, hojas de al menos seis muestras, semilla fija 2025. Ningún ajuste utiliza el periodo de evaluación. Ventanas con faltantes se excluyen.</p><p>Un año, una ubicación y un único corte temporal no prueban generalización. Las importancias no son causales.</p></details></div></details>`;mountSeedExperience($('#aiSeedExperience'),input,false);$('#aiReport').onclick=()=>download('nortex-modulos-ia.json',report);$('#aiXML').onclick=()=>download('nortex-xai.xml',xmlPrompt(report),'application/xml');}
 $('#aiNASA').onclick=async()=>{const b=$('#aiNASA');b.disabled=true;$('#aiStatus').textContent='Consultando NASA…';try{const p=context.point,key=`nortex-power-${p.lat.toFixed(3)}-${p.lon.toFixed(3)}`;let data;try{data=JSON.parse(localStorage.getItem(key)||'null')}catch{}if(!data){const q=new URLSearchParams({parameters:'T2M_MAX,PRECTOTCORR',community:'AG',latitude:p.lat.toFixed(3),longitude:p.lon.toFixed(3),start:'20250101',end:'20251231',format:'JSON','time-standard':'LST'});const response=await fetch(`https://power.larc.nasa.gov/api/temporal/daily/point?${q}`,{signal:AbortSignal.timeout(45000)});if(!response.ok)throw Error(`NASA ${response.status}`);data=await response.json();}const pars=data.properties?.parameter;if(!pars?.T2M_MAX||!pars.PRECTOTCORR)throw Error('Parámetros no disponibles');const clean=v=>typeof v==='number'&&Number.isFinite(v)&&v!==-999?v:null;rows=Object.keys(pars.T2M_MAX).sort().map(d=>({date:d.slice(0,4)+'-'+d.slice(4,6)+'-'+d.slice(6,8),temp:clean(pars.T2M_MAX[d]),rain:clean(pars.PRECTOTCORR[d])}));source='NASA POWER · histórico de referencia';if(root.isConnected)context.onClimate?.(rows,source);try{localStorage.setItem(key,JSON.stringify(data))}catch{}if(root.isConnected){ml=null;$('#aiML').innerHTML='';setSource();update();$('#aiStatus').textContent='Datos listos para el experimento.';}}catch(e){if(root.isConnected)$('#aiStatus').textContent=e.message;}finally{if(root.isConnected)b.disabled=false;}};
 $('#aiTrain').onclick=()=>{const b=$('#aiTrain');b.disabled=true;$('#aiNASA').disabled=true;$('#aiStatus').textContent='Entrenando árboles y evaluando el periodo reservado…';const worker=new Worker(new URL('./worker.js',import.meta.url),{type:'module'});const finish=()=>{worker.terminate();if(root.isConnected){b.disabled=false;$('#aiNASA').disabled=false;}};worker.onerror=()=>{if(root.isConnected)$('#aiStatus').textContent='No se pudo ejecutar el modelo en este navegador.';finish();};worker.onmessage=({data})=>{if(root.isConnected){if(data.error)$('#aiStatus').textContent=data.error;else{ml=data.result;context.onPrediction?.(ml);$('#aiStatus').textContent='Experimento completado. Resultados fuera del periodo de entrenamiento.';const e=ml.evaluation;$('#aiML').innerHTML=`<details style="margin-top:12px"><summary>Ver métricas técnicas detalladas (MAE / RMSE)</summary><div class="scroll"><table><tr><th>Modelo</th><th>MAE °C</th><th>RMSE °C</th></tr><tr><td>Random Forest</td><td>${fixed(e.rf.mae)}</td><td>${fixed(e.rf.rmse)}</td></tr><tr><td>Persistencia</td><td>${fixed(e.baseline.mae)}</td><td>${fixed(e.baseline.rmse)}</td></tr></table></div><p>${ml.training.n} muestras de entrenamiento · ${e.n} de evaluación · ${ml.excluded_windows} ventanas excluidas.</p></details>`;renderFriendlyMLTranslation($('#aiML'),ml);update(true);}}finish();};worker.postMessage({rows,source});};update(false);
}
